-- Atomic outcome workflows keep status, history, and leaderboard points in sync.
create or replace function public.complete_item_return(p_item_id uuid) returns void language plpgsql security definer set search_path=public as $$declare v_finder uuid;v_school uuid;begin if not is_school_staff() then raise exception 'Unauthorized';end if;select finder_student_id,school_id into v_finder,v_school from items where id=p_item_id and school_id=current_school_id() for update;if v_school is null then raise exception 'Item not found';end if;update items set status='RETURNED',returned_at=now(),updated_at=now() where id=p_item_id;update claims set status='COMPLETED',updated_at=now() where item_id=p_item_id and status='APPROVED';insert into item_events(item_id,event_type,performed_by) values(p_item_id,'RETURNED',auth.uid());if v_finder is not null then insert into impact_points(school_id,student_id,reason,points,reference_type,reference_id) values(v_school,v_finder,'Helped return a lost item',10,'item',p_item_id) on conflict do nothing;end if;end$$;
create or replace function public.complete_donation(p_donation_id uuid,p_recipient_id uuid) returns void language plpgsql security definer set search_path=public as $$declare v_donor uuid;v_school uuid;begin select donor_id,school_id into v_donor,v_school from donations where id=p_donation_id and (donor_id=auth.uid() or (school_id=current_school_id() and is_school_staff())) for update;if v_school is null then raise exception 'Unauthorized';end if;update donations set status='GIVEN',recipient_id=p_recipient_id,given_at=now(),updated_at=now() where id=p_donation_id;insert into impact_points(school_id,student_id,reason,points,reference_type,reference_id) values(v_school,v_donor,'Completed a student donation',15,'donation',p_donation_id) on conflict do nothing;end$$;
grant execute on function public.complete_item_return(uuid) to authenticated;grant execute on function public.complete_donation(uuid,uuid) to authenticated;
